/* Table */
table { width: 100%; border-collapse: collapse; }
th, td { border-bottom: 1px solid #444; padding: 8px 12px; text-align: left; vertical-align: top; white-space: pre-line; font-size: 0.75rem; }
th { background: #2d2d38; color: #fff; text-align: left; }

/* COLUMN WIDHTS - prevent overlap */
th.trophy, td.trophy { min-width: 200px; }
th.grade, td.grade { min-width: 60px; text-align: center; }
th.earned, td.earned { min-width: 50px; text-align: center; }
th.guide, td.guide { min-width: 300px; }

/* Trophy names - truncate if needed */
.trophy-name { display: block; }
.trophy-name:hover { text-decoration: underline; }

/* Spoiler note */
.spoiler-note { font-size: 0.65rem; color: #888; margin-left: 4px; }

/* View-specific */
#rows tr { cursor: pointer; }
#rows tr:hover { background: #2a2a3a; }

/* Modal */
dialog { border: none; border-radius: 8px; padding: 24px; background: #2d2d38; color: #fff; margin: 24px; }
dialog h2 { margin-top: 0; font-size: 1.2rem; }
.details { margin: 12px 0; font-size: 0.85rem; }
details + details { margin-top: 8px; }
dialog button { margin-top: 16px; padding: 8px 16px; }

/* Source matrix */
.source-matrix a { color: #bd93f9; font-size: 0.7rem; text-decoration: none; margin-right: 4px; }
.source-matrix a:hover { text-decoration: underline; }
